:root {
  --bg-card: #e8f4f8;
  --border-card: #7bbfd4;
  --header-bg: #2a7f9e;
  --header-text: #ffffff;
  --badge-bg: #f4a020;
  --badge-text: #ffffff;
  --label-color: #5a8fa0;
  --value-color: #1a3d4f;
  --row-border: #b8dce9;
  --footer-bg: #d0eaf3;
  --footer-text: #2a7f9e;
  --id-color: #7bbfd4;
}

article.tide-tag {
  background: var(--bg-card);
  border: 2px solid var(--border-card);
  border-radius: 14px;
  width: 340px;
  overflow: hidden;
  margin: 0 auto;
}

.tag-header {
  background: var(--header-bg);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
}

.tag-icon {
  font-size: 28px;
  line-height: 1;
}

.tag-title {
  flex: 1;
}

.tag-title h2 {
  color: var(--header-text);
  font-size: 17px;
  font-weight: 700;
  margin: 0;
  line-height: 1.2;
}

.tag-location {
  color: var(--header-text);
  font-size: 12px;
  margin: 0;
  opacity: 0.8;
}

.tag-badge {
  background: var(--badge-bg);
  color: var(--badge-text);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 3px 8px;
  border-radius: 20px;
}

.tag-body {
  padding: 10px 16px;
  display: flex;
  flex-direction: column;
  gap: 0;
}

.detail-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 9px 0;
  border-bottom: 1px solid var(--row-border);
}

.detail-row:last-child {
  border-bottom: none;
}

.detail-label {
  color: var(--label-color);
  font-size: 13px;
  font-weight: 500;
}

.detail-value {
  color: var(--value-color);
  font-size: 14px;
  font-weight: 700;
}

.tag-footer {
  background: var(--footer-bg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 9px 16px;
  border-top: 1px solid var(--border-card);
}

.tag-date {
  color: var(--footer-text);
  font-size: 12px;
  font-weight: 600;
}

.tag-id {
  color: var(--id-color);
  font-size: 12px;
  font-weight: 500;
}
